import Testing
@testable import ClipDockCore

@Suite("Skip rules")
struct SkipRulesTests {
    let rules = SkipRules()
    let text = "public.utf8-plain-text"

    @Test("Password-manager markers are skipped", arguments: [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ])
    func skipsMarkers(marker: String) {
        #expect(rules.reasonBeforeReading(types: [text, marker], sourceBundleID: "com.apple.Safari") == .concealed)
    }

    @Test("ClipDock's own writes are skipped")
    func skipsOwnWrites() {
        #expect(rules.reasonBeforeReading(types: [text, SkipRules.internalType], sourceBundleID: nil) == .ownWrite)
    }

    @Test("Default ignored apps are skipped", arguments: SkipRules.defaultIgnoredBundleIDs)
    func skipsIgnoredApps(bundleID: String) {
        #expect(rules.reasonBeforeReading(types: [text], sourceBundleID: bundleID) == .ignoredApp)
    }

    @Test("Ignored-app match ignores case")
    func ignoredAppIsCaseInsensitive() {
        #expect(rules.reasonBeforeReading(types: [text], sourceBundleID: "COM.APPLE.PASSWORDS") == .ignoredApp)
    }

    @Test("A custom ignored list replaces the default")
    func customIgnoredList() {
        let custom = SkipRules(ignoredBundleIDs: ["com.example.secret"])
        #expect(custom.reasonBeforeReading(types: [text], sourceBundleID: "com.example.secret") == .ignoredApp)
        #expect(custom.reasonBeforeReading(types: [text], sourceBundleID: "com.apple.Passwords") == nil)
    }

    @Test("Ordinary copies pass, with or without a known source")
    func allowsOrdinaryCopies() {
        #expect(rules.reasonBeforeReading(types: [text, "public.rtf"], sourceBundleID: "com.apple.TextEdit") == nil)
        #expect(rules.reasonBeforeReading(types: ["public.png"], sourceBundleID: nil) == nil)
    }

    @Test("An empty pasteboard is skipped")
    func skipsEmpty() {
        #expect(rules.reasonBeforeReading(types: [], sourceBundleID: "com.apple.TextEdit") == .empty)
    }

    @Test("Items over 10 MB are skipped; exactly 10 MB is kept")
    func sizeLimit() {
        let limit = 10 * 1024 * 1024
        #expect(rules.reasonAfterReading(byteSize: limit) == nil)
        #expect(rules.reasonAfterReading(byteSize: limit + 1) == .tooLarge(bytes: limit + 1))
    }
}
